tasks.answer:
def check_brackets(s):
    pairs = {')': '(', '}': '{', ']': '['}
    stack = []
    for ch in s:
        if ch in '({[':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

for test in ['A[(i+1)] = 0', 'if ((i==0) && (j==0)', 'while (i < 10) ) :']:
    print(test, '→', check_brackets(test))

